def propose(ctx: dict) -> dict:
    """Analyse the context and propose a plan for building the missing skill."""
    skill_id = ctx.get("skill_id", "unknown")
    goal = ctx.get("goal", "build missing skill")
    constraints = ctx.get("constraints", [])

    plan_steps = [
        f"Identify requirements for skill '{skill_id}'",
        "Gather relevant context from workspace",
        "Generate skill scaffold with propose/apply/test",
        "Validate against constraints",
        "Write artefacts to artifacts_dir",
    ]

    return {
        "ok": True,
        "skill_id": skill_id,
        "goal": goal,
        "constraints": constraints,
        "plan": plan_steps,
        "description": f"Proposal to {goal} for skill '{skill_id}'",
    }


def apply(ctx: dict) -> dict:
    """Execute the skill: build the missing skill artefact."""
    skill_id = ctx.get("skill_id", "unknown")
    goal = ctx.get("goal", "build missing skill")
    dry_run = ctx.get("dry_run", False)

    skeleton = (
        '"""Auto-generated skill: {sid}."""\n\n'
        "def propose(ctx: dict) -> dict:\n"
        '    return {{"ok": True, "plan": ["implement {sid}"]}}\n\n'
        "def apply(ctx: dict) -> dict:\n"
        '    return {{"ok": True, "result": "{sid} applied"}}\n\n'
        "def test(ctx: dict) -> dict:\n"
        '    return {{"ok": True}}\n'
    ).format(sid=skill_id)

    if dry_run:
        return {
            "ok": True,
            "skill_id": skill_id,
            "dry_run": True,
            "would_write": "skill.py",
            "skeleton_lines": skeleton.count("\n") + 1,
        }

    artifacts_dir = ctx.get("artifacts_dir", "")
    wrote_path = None

    if artifacts_dir:
        target = artifacts_dir.rstrip("/").rstrip("\\") + "/skill.py"
        try:
            with open(target, "w", encoding="utf-8") as fh:
                fh.write(skeleton)
            wrote_path = target
        except Exception as exc:
            return {
                "ok": False,
                "skill_id": skill_id,
                "error": str(exc),
            }

    return {
        "ok": True,
        "skill_id": skill_id,
        "goal": goal,
        "wrote": wrote_path,
        "skeleton_preview": skeleton[:200],
    }


